<?php get_header(); ?><div class="sf-grid"><?php if(have_posts()):while(have_posts()):the_post(); ?><article class="sf-card"><?php if(has_post_thumbnail())the_post_thumbnail('large'); ?><div class="sf-card-body"><div class="sf-meta"><?php echo esc_html(get_post_meta(get_the_ID(),'sfv3_source',true)); ?> · <?php echo esc_html(get_the_date('Y/m/d H:i')); ?></div><h2 class="sf-title"><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h2><div class="sf-meta"><?php echo esc_html(get_the_excerpt()); ?></div></div></article><?php endwhile;else:?><p>هنوز خبری منتشر نشده است.</p><?php endif; ?></div><?php get_footer(); ?>